import{r as e}from"./rolldown-runtime-hePW80VL.js";import{Vt as t}from"./icons-CW52Kier.js";import{t as n}from"./react-CwoOtI55.js";import{c as r,d as i,l as a,n as o,o as s,s as c,t as l}from"./router-DWpkaxKs.js";import{a as u,c as d,i as f,l as p,n as m,o as h,r as g,s as _,t as v,u as ee}from"./motion-BvsT_lH_.js";import{n as y,t as b}from"./Icon-DZCoA67a.js";(function(){let e=document.createElement(`link`).relList;if(e&&e.supports&&e.supports(`modulepreload`))return;for(let e of document.querySelectorAll(`link[rel="modulepreload"]`))n(e);new MutationObserver(e=>{for(let t of e)if(t.type===`childList`)for(let e of t.addedNodes)e.tagName===`LINK`&&e.rel===`modulepreload`&&n(e)}).observe(document,{childList:!0,subtree:!0});function t(e){let t={};return e.integrity&&(t.integrity=e.integrity),e.referrerPolicy&&(t.referrerPolicy=e.referrerPolicy),t.credentials=e.crossOrigin===`use-credentials`?`include`:e.crossOrigin===`anonymous`?`omit`:`same-origin`,t}function n(e){if(e.ep)return;e.ep=!0;let n=t(e);fetch(e.href,n)}})();var x=e(t(),1),te=n(),ne=`/api/public`;async function S(e,{timeout:t=4e3}={}){let n=new AbortController,r=setTimeout(()=>n.abort(),t),i;try{i=await fetch(`${ne}${e}`,{signal:n.signal,headers:{Accept:`application/json`}})}finally{clearTimeout(r)}if(!i.ok)throw Error(`Public API ${e} responded ${i.status}`);let a=await i.json().catch(()=>null);if(!a||a.success===!1)throw Error(`Public API ${e} returned an unexpected payload`);return a.data??null}var C={bootstrap:()=>S(`/bootstrap`),projects:()=>S(`/projects`),project:e=>S(`/projects/${encodeURIComponent(e)}`),skills:()=>S(`/skills`),experience:()=>S(`/experience`),security:()=>S(`/security`),engineering:()=>S(`/engineering`),apiDocs:()=>S(`/api-docs`),seo:()=>S(`/seo`),profile:()=>S(`/profile`)},w={name:`Aswapathy Raj`,initials:`AR`,title:`Full-Stack Developer`,headline:`I build modern, scalable web applications from interface to database and deployment.`,availability:{available:!0,label:`Available for opportunities`,unavailableLabel:`Currently heads-down on a project`},location:``,timezone:``,email:`aswapathyraj@gmail.com`,github:`https://github.com/aswapathyraj`,linkedin:``,resume:`/resume.pdf`,githubUsername:`aswapathyraj`,siteUrl:`https://portfolio-v2-weld-five.vercel.app`,seo:{titleTemplate:`%s — Aswapathy Raj`,defaultTitle:`Aswapathy Raj — Full-Stack Developer`,description:`Portfolio of Aswapathy Raj, a full-stack developer building modern web applications with React, Node.js, APIs, and databases.`,keywords:[`full-stack developer`,`React developer`,`Node.js`,`Express`,`REST API`,`SQLite`,`Tailwind CSS`],ogImage:`/og-image.png`,twitterHandle:``},features:{customCursor:!0,themeToggle:!0,githubActivity:!0,scrollProgressBar:!0},contactForm:{provider:`none`,endpoint:``}},T=e=>typeof e==`string`?e.trim().length>0:!!e,E=(e=`/`)=>{let t=w.siteUrl.replace(/\/+$/,``),n=e.startsWith(`/`)?e:`/${e}`;return t?`${t}${n}`:n},D=[{slug:`qr-food-ordering`,title:`QR Food Ordering System`,subtitle:`Contactless Restaurant Ordering`,category:`Full-Stack Application`,year:`2025`,status:`shipped`,featured:!0,accent:`accent2`,image:``,screenshots:[],github:`https://github.com/aswapathyraj/food-ordering-app`,liveDemo:``,summary:`A QR-based restaurant ordering platform: scan the table code, browse the menu, build a cart, place the order, and track its status — with an admin dashboard behind it.`,description:`Each table has its own QR code that opens the menu with the table already identified. Customers order without an account; staff manage the menu and watch orders move through the kitchen from a dashboard.`,problem:`Ordering from a phone only helps if it is faster than waving someone down. That rules out a signup flow, so the order has to be tied to a table rather than a user account — while still making sure a customer at table 4 cannot read or modify table 7's order.`,solution:`The table identifier is encoded in the QR URL and carried as an opaque token on every request, so the menu, the cart, and the order all resolve to a table without authentication. Orders are append-only rows with a status column that the admin dashboard advances; the customer's tracking view polls the same order resource it created.`,features:[{title:`QR scanning`,detail:`Table-specific codes deep-link straight into the menu for that table.`},{title:`Digital menu`,detail:`Categorised items served from the API, editable without a redeploy.`},{title:`Cart`,detail:`Client-side cart with quantities and a running total before submission.`},{title:`Order placement`,detail:`One POST creates the order and its line items together.`},{title:`Order status tracking`,detail:`Customers follow placed → preparing → ready without reloading.`},{title:`Admin dashboard`,detail:`Live order queue with status transitions for kitchen staff.`},{title:`QR generation`,detail:`Codes generated per table from the admin side.`},{title:`Menu management`,detail:`Create, edit, and toggle availability of menu items.`},{title:`Revenue view`,detail:`Totals aggregated from completed orders in the database.`}],technologies:[`react`,`tailwind`,`html`,`css`,`javascript`,`nodejs`,`express`,`rest`,`sqlite`,`sql`,`qrcode`,`git`],architecture:{note:`The table identity travels with the request, so ordering needs no login.`,rows:[[{id:`customer`,label:`Customer`,sub:`Scans the table QR code`,kind:`client`,icon:`qrCode`}],[{id:`spa`,label:`React Application`,sub:`Menu · cart · order tracking`,kind:`edge`,icon:`react`}],[{id:`api`,label:`REST API`,sub:`JSON over HTTP`,kind:`api`,icon:`network`}],[{id:`backend`,label:`Express Backend`,sub:`Menu, orders, status transitions`,kind:`service`,icon:`server`}],[{id:`db`,label:`SQLite Database`,sub:`tables · menu_items · orders · order_items`,kind:`data`,icon:`database`}]]},database:{note:"Orders are append-only; `status` is the only column that moves after creation.",tables:[{name:`tables`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`label`,type:`TEXT`,note:`e.g. "Table 4"`},{name:`qr_token`,type:`TEXT`,key:`UNIQUE`}]},{name:`menu_items`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`name`,type:`TEXT`},{name:`category`,type:`TEXT`},{name:`price`,type:`DECIMAL`},{name:`is_available`,type:`BOOLEAN`}]},{name:`orders`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`table_id`,type:`INTEGER`,key:`FK`,ref:`tables.id`},{name:`status`,type:`TEXT`,note:`placed · preparing · ready · served`},{name:`total`,type:`DECIMAL`},{name:`created_at`,type:`DATETIME`}]},{name:`order_items`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`order_id`,type:`INTEGER`,key:`FK`,ref:`orders.id`},{name:`menu_item_id`,type:`INTEGER`,key:`FK`,ref:`menu_items.id`},{name:`quantity`,type:`INTEGER`},{name:`unit_price`,type:`DECIMAL`,note:`captured at order time`}]}]},auth:[{label:`Customer flow`,detail:`No account. The QR token identifies the table and scopes what the request can read.`},{label:`Admin flow`,detail:`Staff routes sit behind a login; menu and status mutations are admin-only.`},{label:`Scoping`,detail:`Order reads are filtered by the requesting table's token rather than by an id in the URL.`}],challenges:[{title:`Identity without accounts`,detail:`A guest ordering flow still needs a subject. Deriving it from the QR token meant the table became the identity — which immediately raised the question of what stops someone editing the URL, and pushed order lookups to be filtered by token instead of by a guessable order id.`},{title:`Prices that must not drift`,detail:"If a line item only references `menu_items.id`, changing a price rewrites the history of every past order. Copying `unit_price` onto `order_items` at order time keeps historical totals accurate — a small denormalisation with a clear reason."},{title:`Status that two clients agree on`,detail:`The kitchen dashboard writes the status and the customer view reads it. Keeping status transitions server-validated meant the order could never land in a state neither screen knew how to render.`},{title:`Usable on a real phone, in a real restaurant`,detail:`The whole flow happens one-handed on a small screen in poor light. Tap targets, a persistent cart summary, and legible contrast mattered more than any visual flourish.`}],learnings:[`Capture values that must not change with history — a foreign key is a reference, not a snapshot.`,`Not every flow needs authentication, but every flow needs scoping.`,`Two clients reading the same resource is a strong argument for validating transitions on the server.`,`A dashboard is a product too: the kitchen view needed as much design attention as the customer view.`],outcome:[`Full loop working: scan → browse → cart → order → live status, with staff advancing orders from the dashboard.`,`Menu and table QR codes are managed from the admin side without touching code.`]},{slug:`developer-portfolio`,title:`Developer Portfolio`,subtitle:`This Site`,category:`Frontend Engineering`,year:`2026`,status:`shipped`,featured:!1,accent:`accent`,image:``,screenshots:[],github:``,liveDemo:``,summary:`The site you are reading. Built as a component system rather than a page, with the technical sections driven entirely by data files.`,description:`Rather than describing skills in prose, the portfolio demonstrates them: the tech-stack explorer cross-references real projects, the API explorer runs the same validation module as the contact form, and the architecture and schema diagrams render from the same project data as the case studies.`,problem:`A portfolio that only lists technologies asks the reader to take its word for it. The interesting constraint was making the site itself the evidence — without inventing metrics or shipping a page of decorative animation.`,solution:"A token-driven design system in Tailwind CSS v4 where a single `data-theme` attribute re-themes the whole site, reusable Framer Motion variants that collapse under `prefers-reduced-motion`, and a strict data/UI split so every section is a renderer over a config file.",features:[{title:`Token-driven theming`,detail:`One palette layer; light and dark share every component.`},{title:`Interactive tech explorer`,detail:`Selecting a technology highlights the projects that actually use it.`},{title:`Case-study routes`,detail:`React Router routes per project, deep-linkable and code-split.`},{title:`Mock API explorer`,detail:`Labelled in-browser mock — real status codes and error shapes, no fake network calls.`},{title:`Schema + architecture diagrams`,detail:`Rendered from project data; reflow to a vertical stack on mobile.`},{title:`Reduced-motion support`,detail:`Animation is disabled at the source, not just shortened.`},{title:`Configurable everything`,detail:`Links, stats, SEO, and feature flags live in src/config.js.`}],technologies:[`react`,`javascript`,`html`,`css`,`tailwind`,`framer`,`rest`,`git`,`vercel`,`vscode`],architecture:{note:`No backend. The data layer is the API.`,rows:[[{id:`visitor`,label:`Visitor`,sub:`Any device, keyboard or pointer`,kind:`client`,icon:`users`}],[{id:`app`,label:`React + Vite SPA`,sub:`Route-level code splitting`,kind:`edge`,icon:`react`}],[{id:`ds`,label:`Design System`,sub:`Tailwind v4 tokens`,kind:`service`,icon:`palette`},{id:`motion`,label:`Motion Layer`,sub:`Shared variants, reduced-motion aware`,kind:`service`,icon:`zap`},{id:`mock`,label:`Mock API`,sub:`Validation shared with the live form`,kind:`service`,icon:`network`}],[{id:`data`,label:`Data Layer`,sub:`config.js · data/*.js`,kind:`data`,icon:`database`}],[{id:`host`,label:`Static Hosting`,sub:`Prebuilt assets on a CDN`,kind:`infra`,icon:`rocket`}]]},database:null,auth:[{label:`No auth surface`,detail:`A static site with no accounts has no session to steal — the safest option was fewer moving parts.`},{label:`No secrets in the client`,detail:`The GitHub integration uses only unauthenticated public endpoints.`},{label:`Honest form handling`,detail:`With no mail provider configured, the form validates and hands over to email rather than faking a success state.`}],challenges:[{title:`Two themes without doubling the CSS`,detail:"Declaring the Tailwind theme `inline` so utilities compile to `var(--p-…)` meant light mode became a second block of variable declarations instead of a `dark:` variant on every element."},{title:`Motion that respects the reader`,detail:'Reduced-motion support that only shortens durations still moves the page. Framer\'s `reducedMotion="user"` plus variants that fall back to opacity-only transitions removes the movement itself.'},{title:`Diagrams that survive 320px`,detail:`The architecture and schema visualisations are the easiest thing to break on a phone. Modelling them as rows of nodes rather than absolute positions let the same data render as a grid on desktop and a single column on mobile.`}],learnings:[`A design system is mostly a naming problem. Once the tokens were right, the components stopped arguing.`,`Keeping content in data files made the components smaller and the site far easier to extend.`,`Demonstrating a skill is more convincing than listing it — and harder to fake.`],outcome:[`Every technical section renders from data, so adding a project or skill needs no component changes.`,`Light and dark themes, keyboard navigation, and reduced-motion paths all covered by the same component set.`]},{slug:`are-you-a-girl`,title:`Are You A Girl?`,subtitle:`Interactive Prank Quiz Experience`,category:`Interactive Web Experience`,year:`2026`,status:`shipped`,featured:!0,accent:`accent2`,image:``,screenshots:[],github:`https://github.com/aswapathyraj/Are-You-A-Girl`,liveDemo:`https://are-you-a-girl.vercel.app`,summary:`A playful interactive prank quiz that turns a simple Yes/No questionnaire into an unpredictable experience using evasive buttons, animated interactions, fake scanning, sound effects, and humorous results.`,description:`Are You A Girl? is a frontend-only interactive prank website designed to feel like a serious personality verification system while progressively revealing the joke. Users go through a series of Yes/No questions, but the NO button behaves unpredictably — moving away, shrinking, disappearing, or becoming unavailable. After the quiz, a fake scanning process analyzes the user and produces exaggerated personality statistics before the final reveal.`,problem:`Traditional quiz interfaces are predictable: users read a question, select an answer, and continue. The goal was to break that pattern and make the interface itself part of the entertainment. The challenge was creating interactions that feel surprising and funny while remaining responsive, lightweight, and easy to use.`,solution:`The application uses React state and animation logic to control the behavior of each quiz question. The NO button can change position, size, visibility, and behavior based on the current question. A fake cursor is used when necessary to guide the interaction toward YES, followed by a simulated scanning process and humorous result generation.`,features:[{title:`Interactive quiz`,detail:`A sequence of Yes/No questions designed around unpredictable interactions.`},{title:`Evasive NO button`,detail:`The NO button moves, shrinks, shakes, disappears, or changes behavior depending on the question.`},{title:`Fake cursor`,detail:`An in-page cursor animation creates the illusion of an automatic interaction without controlling the user's real mouse.`},{title:`Forced interactions`,detail:`When the NO option becomes unavailable, the experience automatically guides the user toward YES.`},{title:`Fake scanning`,detail:`A simulated 0% to 100% scanning sequence creates a convincing verification-style experience.`},{title:`Personality analysis`,detail:`The application generates exaggerated and humorous personality statistics.`},{title:`Sound effects`,detail:`Browser-generated audio feedback adds another layer of interaction to important events.`},{title:`Sound control`,detail:`Users can enable or disable the generated sound effects through a dedicated control.`},{title:`Final reveal`,detail:`The verification experience concludes with a comedic result and second-opinion style reveal.`}],technologies:[`react`,`vite`,`html`,`css`,`tailwind`,`javascript`,`framer`,`lucide-react`,`web-audio-api`,`git`],architecture:{note:`The application is a client-side React experience with quiz state, animation state, and result state managed entirely in the browser.`,rows:[[{id:`user`,label:`User`,sub:`Interacts with the quiz`,kind:`client`,icon:`user`}],[{id:`react`,label:`React Application`,sub:`Quiz · interactions · results`,kind:`edge`,icon:`react`}],[{id:`quiz`,label:`Quiz Engine`,sub:`Questions · answers · button behavior`,kind:`service`,icon:`zap`}],[{id:`animation`,label:`Animation Layer`,sub:`Motion · fake cursor · scanning`,kind:`service`,icon:`sparkles`}],[{id:`audio`,label:`Web Audio API`,sub:`Generated interaction sounds`,kind:`data`,icon:`volume2`}]]},database:null,auth:[{label:`User flow`,detail:`No account or authentication is required. The entire experience runs directly in the browser.`},{label:`Data collection`,detail:`The application does not require a backend database or user account to complete the experience.`}],challenges:[{title:`Making the NO button unpredictable`,detail:`The core joke depends on the NO button behaving differently across questions. Implementing movement, resizing, disappearance, and automatic interactions required carefully coordinating React state with animation state.`},{title:`Keeping interactions responsive`,detail:`A button that moves around the screen can easily become frustrating or unusable on smaller devices. The interaction logic needed to remain visually interesting while keeping the controls accessible.`},{title:`Coordinating animation states`,detail:`Quiz progression, button movement, fake cursor behavior, scanning progress, and result transitions all needed to happen in the correct order without conflicting with one another.`},{title:`Creating a convincing fake verification flow`,detail:`The scanning sequence and result screen needed to temporarily feel authentic before revealing the joke. Progress animation, typography, motion, and sound were combined to sell the illusion.`}],learnings:[`Interactive interfaces can use unexpected behavior as a core part of the user experience.`,`React state can be combined with animation libraries to create complex interaction flows without a backend.`,`Small UI details such as sound, cursor movement, and timing can dramatically improve engagement.`,`Responsive design becomes more challenging when interface elements intentionally move around the screen.`,`A frontend-only application can still deliver a complete and memorable product experience.`],outcome:[`Created a complete interactive prank experience from landing screen to final reveal.`,`Implemented custom evasive-button mechanics with multiple interaction behaviors.`,`Built animated fake scanning and personality-analysis screens.`,`Added browser-generated sound effects without requiring external audio assets.`,`Published the project publicly on GitHub and deployed it as a web application.`]},{slug:`cameraport`,title:`CameraPort`,subtitle:`Camera Service Management System`,category:`Full-Stack Application`,year:`2025`,status:`shipped`,featured:!1,accent:`accent`,image:``,screenshots:[],github:`https://github.com/aswapathyraj/Cameraport`,liveDemo:``,summary:`A camera repair and service management platform for managing service records, customers, administrators, invoices, and operational data through a responsive dashboard.`,description:`CameraPort is a full-stack camera service management system built for organizing camera repair and maintenance operations. The application provides role-based authentication for admins and super admins, complete service record management, CSV import and export, PDF invoice generation, dashboard analytics, and responsive interfaces for managing service operations efficiently.`,problem:`Managing camera repair records manually can make it difficult to track service requests, update repair information, generate invoices, and monitor overall service activity. The system needed a centralized platform where administrators could manage records efficiently while maintaining different levels of access for regular admins and super admins.`,solution:`CameraPort combines a Flask backend with a lightweight HTML, CSS, and JavaScript frontend. Service records are stored in SQLite and exposed through backend routes, while role-based sessions control administrative access. The dashboard provides service statistics and recent activity, while CSV tools support bulk data management and ReportLab generates PDF invoices directly from service records.`,features:[{title:`Secure authentication`,detail:`Session-based login and logout with role-aware access for administrators.`},{title:`Role-based access`,detail:`Admins manage their own service records while super admins have broader management and account privileges.`},{title:`Service record management`,detail:`Create, view, edit, and delete camera repair and service records with validation.`},{title:`Interactive dashboard`,detail:`Displays service statistics, recent activity, and status distribution through dashboard visualizations.`},{title:`Chart analytics`,detail:`Chart.js visualizations provide a quick overview of service record status distribution.`},{title:`CSV import`,detail:`Bulk service records can be uploaded through CSV files for faster data entry.`},{title:`CSV export`,detail:`Filtered service information can be exported as CSV for reporting and external processing.`},{title:`PDF invoices`,detail:`Individual service records can be converted into professionally formatted PDF invoices using ReportLab.`},{title:`Bulk deletion`,detail:`Multiple service records can be removed efficiently from the management interface.`},{title:`Responsive interface`,detail:`The dashboard and management screens are designed to work across desktop and mobile devices.`},{title:`Backend logging`,detail:`Application errors and debugging information are recorded through backend logging.`}],technologies:[`python`,`flask`,`html`,`css`,`javascript`,`sqlite`,`flask-session`,`reportlab`,`chart.js`,`fetch-api`,`csv`,`sha-256`,`font-awesome`,`git`],architecture:{note:`CameraPort follows a lightweight full-stack architecture where the browser communicates with a Flask backend, which handles authentication, service records, reporting, and database operations.`,rows:[[{id:`admin`,label:`Administrator`,sub:`Manages service operations`,kind:`client`,icon:`user`}],[{id:`frontend`,label:`Web Frontend`,sub:`HTML · CSS · JavaScript`,kind:`edge`,icon:`layout`}],[{id:`flask`,label:`Flask Backend`,sub:`Authentication · CRUD · API`,kind:`service`,icon:`server`}],[{id:`services`,label:`Application Services`,sub:`CSV · PDF · sessions · logging`,kind:`service`,icon:`settings`}],[{id:`database`,label:`SQLite Database`,sub:`Users · service records`,kind:`data`,icon:`database`}]]},database:{note:`SQLite provides lightweight persistent storage for authentication data and camera service records, while generated invoices and session data are handled by the application services.`,tables:[{name:`users`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`username`,type:`TEXT`,key:`UNIQUE`},{name:`password`,type:`TEXT`,note:`SHA-256 hashed`},{name:`role`,type:`TEXT`,note:`admin · super_admin`}]},{name:`service_records`,columns:[{name:`id`,type:`INTEGER`,key:`PK`},{name:`customer`,type:`TEXT`},{name:`camera`,type:`TEXT`},{name:`service_details`,type:`TEXT`},{name:`status`,type:`TEXT`},{name:`created_at`,type:`DATETIME`}]}]},auth:[{label:`Session authentication`,detail:`Administrators authenticate through a Flask session-based login system before accessing protected management functionality.`},{label:`Admin role`,detail:`Regular admins can manage their permitted service records and perform normal operational tasks.`},{label:`Super admin role`,detail:`Super admins have extended permissions including broader record editing and administrator account management.`},{label:`Protected operations`,detail:`Service management and administrative operations are restricted according to the authenticated user role.`}],challenges:[{title:`Role-based permissions`,detail:`The application needed to support both regular admins and super admins without exposing privileged operations to lower-level users. Permission checks therefore had to be applied to management operations as well as the interface.`},{title:`Managing service records`,detail:`Service records need to support creation, editing, deletion, validation, filtering, and bulk operations while remaining simple enough for day-to-day service-center use.`},{title:`Bulk data management`,detail:`Manually entering large numbers of service records is inefficient, so CSV import and export were added while maintaining validation around incoming data.`},{title:`PDF invoice generation`,detail:`Service data needed to be transformed into a usable invoice document. ReportLab was integrated into the Flask backend to generate PDF invoices directly from individual service records.`},{title:`Dashboard performance`,detail:`The dashboard needed to provide useful operational information without introducing a heavy frontend framework, so the project uses vanilla JavaScript and Chart.js on top of the Flask backend.`}],learnings:[`Learned how to structure a complete Flask-based full-stack application.`,`Improved understanding of session-based authentication and role-based authorization.`,`Learned how to implement CRUD workflows for real-world service records.`,`Learned how to process CSV files for bulk data import and export.`,`Gained experience generating PDF documents dynamically with ReportLab.`,`Learned how to create dashboard visualizations with Chart.js.`,`Improved understanding of SQLite database integration with Flask.`,`Learned how backend logging can help diagnose application errors and operational issues.`],outcome:[`Built a complete camera repair and service management platform.`,`Implemented role-based access for admins and super admins.`,`Created full service record CRUD functionality.`,`Added CSV import and export for bulk data management.`,`Implemented PDF invoice generation from service records.`,`Created an interactive dashboard with service statistics and Chart.js visualizations.`,`Built a responsive interface using HTML, CSS, and vanilla JavaScript.`,`Packaged the system as a lightweight Flask and SQLite application.`]}],re=D.filter(e=>e.status!==`placeholder`);D.filter(e=>e.featured);var ie=e=>D.find(t=>t.slug===e),ae=e=>re.filter(t=>t.technologies.includes(e)),O=[{id:`frontend`,label:`Frontend`,icon:`monitor`,blurb:`Interfaces, state, and the layer the user actually touches.`,skills:[{id:`react`,name:`React`,icon:`react`,description:`Component architecture, hooks, and composition. Every project here is a React client — including this site, built as a component system rather than a page.`},{id:`javascript`,name:`JavaScript`,icon:`javascript`,description:`Modern ES syntax across both client and server. Same language on both sides of the API, which keeps validation logic shareable.`},{id:`html`,name:`HTML`,icon:`html`,description:`Semantic structure first — landmarks, headings, and real buttons — because it is what makes keyboard and screen-reader support possible at all.`},{id:`css`,name:`CSS`,icon:`css`,description:`Layout with Flexbox and Grid, custom properties for theming, and container-aware responsive design rather than shrunken desktop layouts.`},{id:`tailwind`,name:`Tailwind CSS`,icon:`tailwind`,description:`Utility-first styling driven by design tokens. This site defines its palette once and re-themes light/dark from a single attribute.`},{id:`framer`,name:`Framer Motion`,icon:`framer`,description:`Shared animation variants, layout transitions, and scroll-linked motion — with reduced-motion handled at the source.`}]},{id:`backend`,label:`Backend`,icon:`server`,blurb:`The API layer: routing, validation, and business rules.`,skills:[{id:`nodejs`,name:`Node.js`,icon:`nodejs`,description:`Server runtime for both full-stack projects here — request handling, file uploads, and database access.`},{id:`express`,name:`Express.js`,icon:`express`,description:`Routers split by resource, with shared middleware for authentication, authorization, and error handling instead of per-route repetition.`},{id:`rest`,name:`REST APIs`,icon:`rest`,description:`Resource-oriented endpoints, correct status codes, and consistent error shapes so the client can handle failure without string matching.`},{id:`multer`,name:`Multer`,icon:`fileUp`,description:`Multipart upload handling with MIME and size constraints, and server-generated filenames rather than client-supplied ones.`},{id:`python`,name:`Python`,icon:`python`,description:`Powerful backend and scripting language used for automation, APIs, data processing, and building scalable applications.`},{id:`flask`,name:`Flask`,icon:`flask`,description:`Lightweight Python web framework for building fast, flexible backend APIs, web applications, and RESTful services.`}]},{id:`database`,label:`Database`,icon:`database`,blurb:`Schema design, relationships, and queries.`,skills:[{id:`sqlite`,name:`SQLite`,icon:`sqlite`,description:`Relational storage for both platforms — foreign keys, indexes on lookup columns, and transactions around multi-step writes.`},{id:`sql`,name:`SQL`,icon:`sql`,description:`Joins across related tables, aggregates for dashboard figures, and parameterised statements as the default — never string-built queries.`},{id:`dbdesign`,name:`Database Design`,icon:`dbdesign`,description:`Normalising until it hurts, then denormalising on purpose: order line items copy their unit price so past totals stay accurate.`}]},{id:`security`,label:`Auth & Security`,icon:`shield`,blurb:`Who someone is, what they may touch, and what the server refuses.`,skills:[{id:`jwt`,name:`JWT`,icon:`jwt`,description:`Signed tokens issued at login and verified by middleware. Roles travel in the token so routes authorise without an extra query.`},{id:`bcrypt`,name:`bcrypt`,icon:`bcrypt`,description:`Salted password hashing on registration and constant-time comparison on login. Plaintext passwords are never stored.`},{id:`rbac`,name:`Role-Based Access`,icon:`rbac`,description:`Role flags gate the route; row ownership checks gate the record. Authenticated and authorised are treated as separate questions.`},{id:`validation`,name:`Input Validation`,icon:`checkCircle`,description:`Server-side validation as the boundary of trust — client-side checks are for feedback, not enforcement.`},{id:`ratelimit`,name:`Rate Limiting`,icon:`ratelimit`,description:`Request throttling on authentication endpoints so credential guessing costs the attacker time. Applied per route, not globally.`},{id:`csrf`,name:`CSRF Protection`,icon:`csrf`,description:`Understanding why cookie-based sessions need a token that a cross-site form cannot read, and why Bearer-token APIs shift the problem to storage instead.`}]},{id:`tools`,label:`Tools & Deployment`,icon:`terminal`,blurb:`Version control, environment, and getting it live.`,skills:[{id:`git`,name:`Git`,icon:`git`,description:`Feature branches, focused commits, and readable history — so a diff explains a decision rather than a day of work.`},{id:`github`,name:`GitHub`,icon:`github`,description:`Remotes, pull requests, and issues as the record of what changed and why. Every project here lives in its own repository.`},{id:`vscode`,name:`VS Code`,icon:`vscode`,description:`Daily editor — integrated terminal, debugger, and linting kept close to where the code is written.`},{id:`vercel`,name:`Vercel`,icon:`vercel`,description:`Production builds and preview deployments for frontends, with environment variables kept out of the repository.`},{id:`qrcode`,name:`QR Generation`,icon:`qrCode`,description:`Server-side QR generation used to bind a physical table to a scoped URL in the food-ordering platform.`}]}],oe=O.flatMap(e=>e.skills.map(t=>({...t,categoryId:e.id,categoryLabel:e.label,projects:ae(t.id).map(e=>({slug:e.slug,title:e.title}))}))),se=oe.length,ce=[{id:`independent`,role:`Independent Developer`,org:`Self-directed projects`,period:`2024 — Present`,current:!0,icon:`terminal`,summary:`Designing and building full-stack web applications end to end — interface, REST API, relational schema, authentication, and deployment.`,highlights:[`Built two multi-role platforms from an empty repository to a working product.`,`Designed relational schemas first, then derived the API surface from them.`,`Implemented authentication with hashed passwords, signed tokens, and role plus ownership checks.`,`Handled file uploads with type and size constraints and server-generated filenames.`,`Shipped responsive interfaces designed per breakpoint rather than scaled down.`],stack:[`react`,`tailwind`,`nodejs`,`express`,`sqlite`,`jwt`,`git`],projects:[`phlox`,`qr-food-ordering`,`developer-portfolio`]}],le=[],ue=`Project-based experience, described in terms of what was built rather than time served.`,de=[{id:`password-hashing`,label:`Password Security`,value:`bcrypt`,icon:`bcrypt`,level:`implemented`,projects:[`phlox`],summary:`Salted hashing on registration, comparison on login. Plaintext is never stored.`,detail:`Passwords are hashed with bcrypt before they reach the database, so a copy of the users table does not hand over accounts. Login compares the candidate against the stored hash rather than decrypting anything — there is nothing to decrypt.`},{id:`jwt-auth`,label:`Authentication`,value:`JWT`,icon:`jwt`,level:`implemented`,projects:[`phlox`],summary:`Signed tokens issued at login and verified by middleware on protected routes.`,detail:`A successful login returns a signed token that the client sends as a Bearer header. Middleware verifies the signature and attaches the caller to the request, so handlers never parse credentials themselves. An invalid or expired token fails at the boundary with 401 before any handler runs.`},{id:`rbac`,label:`Authorization`,value:`Role-Based Access`,icon:`rbac`,level:`implemented`,projects:[`phlox`,`qr-food-ordering`],summary:`Role flags gate the route; row ownership gates the record.`,detail:`Roles travel in the token, so a route can require artist or admin without an extra query. That alone is not enough: mutating routes also compare the caller's id against the row's owner column, because "logged in" and "allowed to change this record" are different questions.`},{id:`input-validation`,label:`Input Validation`,value:`Server-Side`,icon:`checkCircle`,level:`implemented`,projects:[`phlox`,`qr-food-ordering`],summary:`The server is the trust boundary. Client checks are feedback only.`,detail:`Every payload is validated server-side before it touches the database — required fields, types, ranges, and business rules such as a bid needing to exceed the current high bid. Client-side validation exists to give fast feedback, not to enforce anything.`},{id:`sql-injection`,label:`Query Safety`,value:`Parameterised SQL`,icon:`sql`,level:`implemented`,projects:[`phlox`,`qr-food-ordering`],summary:`Values are bound as parameters, never concatenated into SQL.`,detail:`All statements use placeholders with bound values, so user input is data rather than syntax. This is the default in both projects — there is no code path that builds a query by string concatenation.`},{id:`file-uploads`,label:`File Uploads`,value:`Constrained`,icon:`fileUp`,level:`implemented`,projects:[`phlox`],summary:`MIME type and size limits, with server-generated filenames.`,detail:`Multer restricts accepted MIME types and maximum file size, and stored filenames are generated server-side instead of trusting the client's. Without both, an image upload endpoint is an arbitrary-write primitive.`},{id:`rate-limiting`,label:`API Protection`,value:`Rate Limiting`,icon:`ratelimit`,level:`studied`,projects:[],summary:`Throttling authentication endpoints so credential guessing costs time.`,detail:`The approach I would apply: a per-IP request window on login and registration specifically, rather than one global limit, so brute-force attempts get expensive while normal browsing stays unaffected. I have not shipped this in the projects listed here.`},{id:`csrf`,label:`Request Security`,value:`CSRF Protection`,icon:`csrf`,level:`studied`,projects:[],summary:`Why cookie sessions need a token a cross-site form cannot read.`,detail:`A browser attaches cookies to cross-site form posts automatically, so a cookie-session API needs an unguessable token the attacking page cannot read. Bearer-token APIs like the ones here are not exposed the same way — the trade-off moves to where the token is stored on the client. Understanding which model you are in is the actual skill.`},{id:`session-handling`,label:`Session Handling`,value:`Token Lifecycle`,icon:`timer`,level:`studied`,projects:[],summary:`Expiry, refresh, and what logout can and cannot revoke.`,detail:`A stateless signed token stays valid until it expires, which means logout on the client is not revocation. Short expiry windows, or a server-side denylist when real revocation is required, are the two options — and knowing that a plain JWT gives you neither for free matters more than the implementation detail.`}],fe=`Split honestly between what is running in the projects on this site and what I understand but have not shipped. Nothing here is a claim of an audited or production-hardened system.`,pe={implemented:{label:`Implemented`,description:`Built and running in the linked project`,tone:`accent`},studied:{label:`Studied`,description:`Understood, not yet shipped by me`,tone:`neutral`}},me=[{id:`research`,number:`01`,title:`Research`,icon:`search`,what:`Define the single job the product has to do, and find where existing solutions make it slow or awkward.`,tech:[`Problem framing`,`User flows`,`Scope constraints`],why:`Most wasted work comes from building the right feature for the wrong problem. Narrowing the job early is what makes later trade-offs decidable.`,example:{project:`qr-food-ordering`,note:`The job was "order without waiting". That single constraint eliminated account creation, which then dictated how identity and data scoping had to work.`}},{id:`planning`,number:`02`,title:`Planning`,icon:`clipboard`,what:`Break the product into entities, roles, and the routes that connect them. Decide what ships first.`,tech:[`Entity modelling`,`Role matrix`,`Route planning`],why:`Writing down which role may do what turns permissions from an afterthought into a specification the middleware can implement.`,example:{project:`phlox`,note:`Three roles — visitor, artist, admin — were mapped against every action before any route existed. That table became the authorization middleware.`}},{id:`uiux`,number:`03`,title:`UI / UX`,icon:`penTool`,what:`Design the mobile layout first, then the desktop one. Define every state a screen can be in.`,tech:[`Design tokens`,`Responsive layout`,`Empty / loading / error states`],why:`A screen with no empty state and no error state is half a screen. Deciding them during design stops them from becoming console errors later.`,example:{project:`developer-portfolio`,note:`This site defines one palette as tokens, so light and dark share every component instead of duplicating styles.`}},{id:`frontend`,number:`04`,title:`Frontend`,icon:`react`,what:`Build composable components, keep state as close to where it is used as possible, and render from the API rather than from local copies.`,tech:[`React`,`Component composition`,`Tailwind CSS`,`Framer Motion`],why:`Duplicated state is where most UI bugs live. If the server owns a value, the component should read it, not mirror it.`,example:{project:`phlox`,note:`The client renders navigation and available actions from the decoded JWT, so one build serves all three roles without role-specific bundles.`}},{id:`api`,number:`05`,title:`API`,icon:`network`,what:`Group routes by resource behind shared middleware. Return correct status codes and a consistent error shape.`,tech:[`Node.js`,`Express`,`REST`,`Middleware`],why:`A predictable contract means the frontend can handle failure structurally instead of matching on message strings.`,example:{project:`phlox`,note:`Artworks, auctions, bids, users, and admin each got their own router, with authentication and error handling applied once rather than per route.`}},{id:`database`,number:`06`,title:`Database`,icon:`database`,what:`Design the schema, add foreign keys and indexes, and wrap multi-step writes in transactions.`,tech:[`SQLite`,`SQL`,`Foreign keys`,`Transactions`,`Parameterised queries`],why:`Constraints in the database hold even when application code is wrong. That is the point of putting them there.`,example:{project:`phlox`,note:`Accepting a bid writes the bid row and updates the auction together, so a rejected bid cannot leave the auction partially updated.`}},{id:`auth`,number:`07`,title:`Authentication`,icon:`key`,what:`Hash passwords, issue signed tokens, verify them in middleware, and check record ownership separately from role.`,tech:[`bcrypt`,`JWT`,`Role guards`,`Ownership checks`],why:`A valid token proves identity, not entitlement. Treating them as one question is how users end up editing each other's data.`,example:{project:`phlox`,note:"Artwork mutations compare the token's user id against the row's `user_id`, so an authenticated artist still cannot edit someone else's piece."}},{id:`testing`,number:`08`,title:`Testing`,icon:`testTube`,what:`Walk the unhappy paths on purpose: bad credentials, expired tokens, invalid payloads, and every breakpoint.`,tech:[`Manual path testing`,`API clients`,`Responsive checks`,`Keyboard navigation`],why:`The happy path almost always works. Everything that reaches users as a bug lives one step off it.`,example:{project:`qr-food-ordering`,note:`Editing the identifier in the URL was tested explicitly — which is why order reads are filtered by the table token instead of by a guessable id.`}},{id:`deployment`,number:`09`,title:`Deployment`,icon:`rocket`,what:`Produce a clean production build, keep configuration in environment variables, and verify the deployed build.`,tech:[`Production builds`,`Environment variables`,`Vercel`,`Git-based deploys`],why:`A build that only works locally is not finished. Warnings ignored at this stage are the ones that break in production.`,example:{project:`developer-portfolio`,note:`Personal links, feature flags, and SEO metadata all live in one config file, so deploying to a new domain changes one value.`}}],he={baseUrl:`/api`,version:`v1`,disclaimer:`Demonstration only. These responses are generated in the browser from this site's data layer — no request leaves your device.`},ge=[{id:`list-projects`,method:`GET`,path:`/api/projects`,summary:`List projects`,description:`Returns every documented project with its stack and case-study path. Supports filtering by technology.`,auth:!1,query:[{name:`tech`,type:`string`,required:!1,note:"Skill id, e.g. `react`"},{name:`limit`,type:`integer`,required:!1,note:`Default 10, max 50`}],body:null,statuses:[{code:200,label:`OK`,note:`Array of projects, possibly empty`},{code:400,label:`Bad Request`,note:"`limit` is not a positive integer"}]},{id:`get-project`,method:`GET`,path:`/api/projects/:slug`,summary:`Get one project`,description:`Full case-study payload for a single project: problem, solution, features, architecture, and schema.`,auth:!1,params:[{name:`slug`,type:`string`,required:!0,note:"e.g. `phlox`"}],body:null,statuses:[{code:200,label:`OK`},{code:404,label:`Not Found`,note:`No project with that slug`}],sampleParams:{slug:`phlox`}},{id:`list-skills`,method:`GET`,path:`/api/skills`,summary:`List skills`,description:`Skills grouped by category, each annotated with the projects that actually use it.`,auth:!1,query:[{name:`category`,type:`string`,required:!1,note:`frontend · backend · database · security · tools`}],body:null,statuses:[{code:200,label:`OK`},{code:400,label:`Bad Request`,note:`Unknown category`}]},{id:`get-stack`,method:`GET`,path:`/api/stack`,summary:`Stack summary`,description:`Condensed view of the stack — the shape a "hire me" integration would want.`,auth:!1,body:null,statuses:[{code:200,label:`OK`}]},{id:`post-contact`,method:`POST`,path:`/api/contact`,summary:`Submit a message`,description:`Validates a contact submission. This endpoint runs the same validation module as the live contact form, so its 422 responses are the real ones.`,auth:!1,body:{name:`string, 2–80 chars`,email:`string, valid address`,subject:`string, 3–120 chars`,message:`string, 20–2000 chars`},sampleBody:{name:`Jordan Lee`,email:`jordan@example.com`,subject:`Frontend role — interview`,message:`Saw your PHLOX case study and would like to talk about a full-stack position on our product team.`},statuses:[{code:202,label:`Accepted`,note:`Payload is valid and would be queued for delivery`},{code:422,label:`Unprocessable Entity`,note:`Field-level validation errors`},{code:429,label:`Too Many Requests`,note:`Rate limit — where it would apply in production`}]},{id:`get-health`,method:`GET`,path:`/api/health`,summary:`Health check`,description:`The endpoint every deployment needs and every tutorial skips.`,auth:!1,body:null,statuses:[{code:200,label:`OK`}]}],_e={GET:`accent`,POST:`accent2`,PUT:`warn`,PATCH:`warn`,DELETE:`danger`},ve=D,ye=O,be=oe,xe=ce,Se=de,Ce=me,we=ge,Te=null,Ee=null,De=le,Oe=ue,ke=pe,Ae=fe,je=he,Me=_e,Ne=0,Pe=new Set;function Fe(){Ne+=1,Pe.forEach(e=>e(Ne))}var Ie=e=>(Pe.add(e),()=>Pe.delete(e)),Le=()=>Ne,Re=()=>ve.filter(e=>e.status!==`placeholder`),ze=()=>ve.filter(e=>e.featured),Be=e=>ve.find(t=>t.slug===e),Ve=e=>Re().filter(t=>t.technologies.includes(e)),He=e=>be.find(t=>t.id===e),Ue=(e=[])=>e.map(e=>He(e)?.name??e);function We(){return ve}function Ge(){return ye}function Ke(){return be}function qe(){return xe}function Je(){return Se}function Ye()